public class TokenParserPractice {
    public static void main(String[] args) {
        String[] tokens = {"100", "NaN"};
        try {
            int a = Integer.parseInt(tokens[0]);
            int b = Integer.parseInt(tokens[1]); // Throws NumberFormatException here!
            int c = Integer.parseInt(tokens[2]);
        } catch (NumberFormatException e) {
            System.out.println("Caught parse error");
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("Caught bounds error");
        }
    }
}
